package com.example.jobfinderapp.activities;import android.content.*;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.*;import androidx.recyclerview.widget.*;import com.example.jobfinderapp.R;import com.example.jobfinderapp.adapters.ManageUsersAdapter;import com.example.jobfinderapp.database.DBHelper;import com.example.jobfinderapp.models.User;import com.example.jobfinderapp.utils.UserSession;import java.util.*;
public class ManageUsersActivity extends AppCompatActivity{DBHelper db;int actor;List<Map<String,Object>> rows=new ArrayList<>();ManageUsersAdapter ad;EditText search;String role="",status="";public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_manage_users);db=DBHelper.getInstance(this);UserSession s=new UserSession(this);actor=s.getUserId();User u=actor>0?db.getUserById(actor):null;if(u==null||!DBHelper.ROLE_ADMIN.equals(u.getRole())||!DBHelper.STATUS_ACTIVE.equals(u.getStatus())){s.clear();go();return;}RecyclerView rv=findViewById(R.id.rvUsers);rv.setLayoutManager(new LinearLayoutManager(this));ad=new ManageUsersAdapter(rows,(r)->detail(r));rv.setAdapter(ad);search=findViewById(R.id.etUserSearch);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){load(s.toString());}public void afterTextChanged(Editable e){}});findViewById(R.id.btnBackUsers).setOnClickListener(v->finish());findViewById(R.id.btnFilterAll).setOnClickListener(v->{role="";status="";load(search.getText().toString());});findViewById(R.id.btnFilterCandidate).setOnClickListener(v->{role=DBHelper.ROLE_CANDIDATE;load(search.getText().toString());});findViewById(R.id.btnFilterEmployer).setOnClickListener(v->{role=DBHelper.ROLE_EMPLOYER;load(search.getText().toString());});load("");}void load(String q){rows.clear();rows.addAll(db.getAllUsersForAdmin(q,role,status));ad.notifyDataSetChanged();findViewById(R.id.tvEmptyUsers).setVisibility(rows.isEmpty()?View.VISIBLE:View.GONE);}void detail(Map<String,Object>r){Intent i=new Intent(this,UserDetailActivity.class);i.putExtra("USER_ID",Integer.parseInt(String.valueOf(r.get("id"))));i.putExtra("ACTOR_ID",actor);startActivity(i);}void go(){Intent i=new Intent(this,LoginActivity.class);i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);startActivity(i);finish();}}
